curl -s -X POST https://slack.com/api/users.list -d "token=<TOKEN>" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for m in data['members']:
        name = m.get('real_name','') or ''
        if 'robert' in name.lower() or 'robert' in m.get('name','').lower():
            print(m['id'], m.get('name'), name)
else:
    print(data)
